#include "fresh_fixture_helpers.hpp"
// Selection uses all predeclared training processes and separately metered audits.
int main(int argc,char**argv){try{
 require(argc==5,"usage: select_training MATRIX CAMPAIGN AUDIT_DIR NEW_SELECTION");auto matrix=read_json(argv[1]);files::path campaign=argv[2],audit=argv[3];require(files::is_regular_file(campaign/"stage_complete.json"),"Incomplete stage");auto&declared=matrix.at("rows").array;require(declared.size()==18,"Training matrix count mismatch");auto fixtures=files::path(matrix.at("config").at("training_fixtures").scalar);auto validation=read_json((fixtures/"validation_sidecar.json").string());auto&side=validation.at("entries").array;require(side.size()==2,"Training sidecar count mismatch");std::map<std::string,std::vector<double>> costs;std::map<std::string,bool> eligible;std::map<std::string,J> aa;size_t attempted=0,completed=0;std::ostringstream raw;raw<<"[";
 for(auto&row:declared){auto id=row.at("id").scalar;auto dir=campaign/id;auto e=read_json((dir/"execution.json").string());require(e.at("target_sha256").scalar==row.at("target_sha256").scalar,"Execution target hash mismatch");require(e.at("binary_sha256").scalar==matrix.at(row.at("method").scalar=="ic"?"ic_binary_sha256":"rho_binary_sha256").scalar,"Execution binary hash mismatch");require(num(e.at("resource_envelope").at("address_space_limit_bytes"))==12884901888ULL&&real(e.at("resource_envelope").at("timeout_s"))==2100&&e.at("resource_envelope").at("cpu_affinity").array.size()==1&&num(e.at("resource_envelope").at("cpu_affinity").at(0))==3,"Wrong process envelope");require(digest(dir/"stdout.jsonl")==e.at("stdout_sha256").scalar&&digest(dir/"stderr.txt")==e.at("stderr_sha256").scalar,"Raw output seal mismatch");
  bool pass=e.at("status").scalar=="COMPLETED_VERIFIED";double wall=real(e.at("elapsed_process_wall_s"));require(std::isfinite(wall)&&wall>0,"Invalid process cost");attempted++;if(attempted>1)raw<<",";raw<<"{\"id\":"<<qstr(id)<<",\"status\":"<<qstr(e.at("status").scalar)<<",\"wall_s\":"<<e.at("elapsed_process_wall_s").scalar<<",\"cpu_total_s\":"<<e.at("cpu_total_s").scalar<<",\"peak_rss_bytes\":"<<e.at("peak_rss_bytes").scalar<<",\"execution_sha256\":"<<qstr(digest(dir/"execution.json"))<<"}";
  if(pass){auto answers=lines(dir/"answers.jsonl");require(answers.size()==1,"Wrong singleton answer count");auto&v=answers[0];auto q=point(v.at("target"));size_t target=id.rfind("train_1_",0)==0?1:0;auto d=num(v.at("recovered_scalar"));require(d>0&&d<8569786107849059ULL&&q==point(side[target].at("point"))&&d==num(side[target].at("scalar_validation_only"))&&mul(d,point(matrix.at("config").at("generator")))==q,"Canonical training scalar replay failure");}
  if(row.at("method").scalar=="ic"){auto candidate=row.at("candidate").at("id").scalar;if(!eligible.count(candidate))eligible[candidate]=true;costs[candidate].push_back(wall);if(pass){auto receipt=read_json((audit/(id+".json")).string());require(receipt.at("status").scalar=="PASS"&&num(receipt.at("answers"))==1&&receipt.at("base_sha256").scalar==digest(dir/"base.jsonl")&&receipt.at("trace_sha256").scalar==digest(dir/"rank.jsonl")&&receipt.at("answers_sha256").scalar==digest(dir/"answers.jsonl"),"Missing/bad full rank audit");require(num(receipt.at("columns"))==num(row.at("candidate").at("columns"))&&num(receipt.at("expected_rank_seed"))==num(row.at("rank_seed")),"Audited columns/seed mismatch");}else eligible[candidate]=false;
  }else{require(pass,"Rho training/control failure: preserve evidence and withhold selection");if(id.rfind("aa_",0)==0){auto pair=id.substr(0,id.size()-2);auto answer=lines(dir/"answers.jsonl")[0];if(!aa.count(pair))aa[pair]=answer.at("outcome");else{auto&before=aa[pair];for(auto&[key,v]:before.object){auto&a=answer.at("outcome").at(key);if(v.type=="object"){for(auto&[k,x]:v.object)require(a.at(k).scalar==x.scalar,"A/A charge mismatch");}else require(a.scalar==v.scalar,"A/A work mismatch");}}}}
  if(pass)completed++;
 }
 raw<<"]";std::string selected;double best=INFINITY;std::ostringstream candidates;candidates<<"[";size_t at=0;for(auto&[id,v]:costs){require(v.size()==2,"Candidate missing declared runs");double mean=(v[0]+v[1])/2;if(eligible[id]&&mean<best){best=mean;selected=id;}if(at++)candidates<<",";candidates<<"{\"id\":"<<qstr(id)<<",\"eligible\":"<<(eligible[id]?"true":"false")<<",\"all_attempt_mean_wall_s\":"<<std::setprecision(17)<<mean<<",\"complete_mean_for_selection_s\":"<<(eligible[id]?std::to_string(mean):"null")<<"}";}candidates<<"]";require(costs.size()==5,"Candidate count mismatch");std::ostringstream out;out<<"{\"kind\":\"n83_basis_training_selection\",\"status\":\"TRAINING_REVIEWED\",\"matrix_sha256\":"<<qstr(digest(argv[1]))<<",\"processes_attempted\":"<<attempted<<",\"processes_completed\":"<<completed<<",\"selected_candidate\":"<<(selected.empty()?"null":qstr(selected))<<",\"holdout_control_if_no_selection\":\"C0\",\"candidates\":"<<candidates.str()<<",\"process_costs\":"<<raw.str()<<",\"selector_source_sha256\":"<<qstr(digest(__FILE__))<<",\"selector_executable_sha256\":"<<qstr(digest(argv[0]))<<",\"holdouts_generated\":false,\"winner\":null}\n";create_new(argv[4],out.str());std::cout<<"Selected "<<(selected.empty()?"none":selected)<<" from full training matrix\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
